import {build} from './math.mjs';
const $=s=>document.querySelector(s),colors={elliptic:'#b4e98a',hyperelliptic:'#7bafff',superelliptic:'#b49aff',jacobian:'#edb779'},edgeColors={isogeny:'#b4e98a',cover:'#7bafff',pullback:'#edb779',norm:'#edb779'};let data,zoom=1,selected='E0';
const sup=n=>String(n).split('').map(x=>'⁰¹²³⁴⁵⁶⁷⁸⁹'[+x]||x).join('');
const eq=e=>`y² = x³ + ${e.a}x + ${e.b}`;
function draw(){const es=data.nodes.filter(n=>n.kind==='elliptic'&&n.id!=='E0'),cs=data.nodes.filter(n=>['hyperelliptic','superelliptic'].includes(n.kind));let height=Math.max(650,cs.length*98+100,es.length*85+100),pos=new Map([['E0',{x:330,y:height/2}]]);es.forEach((n,i)=>pos.set(n.id,{x:95+(n.level-1)*85,y:100+i*(height-200)/Math.max(1,es.length-1)}));cs.forEach((n,i)=>{let y=85+i*(height-170)/Math.max(1,cs.length-1);pos.set(n.id,{x:650,y});pos.set('J'+n.id,{x:900,y})});let defs=Object.entries(edgeColors).map(([k,v])=>`<marker id="arrow-${k}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="${v}"/></marker>`).join('');
let edges=data.edges.map(e=>{let s=pos.get(e.source),t=pos.get(e.target),path,lx,ly;if(e.source===e.target){path=`M${s.x-18},${s.y-25} C${s.x-75},${s.y-100} ${s.x+75},${s.y-100} ${s.x+18},${s.y-25}`;lx=s.x;ly=s.y-80}else{let dx=t.x-s.x,dy=t.y-s.y,len=Math.hypot(dx,dy),sx=s.x+dx/len*34,sy=s.y+dy/len*34,tx=t.x-dx/len*36,ty=t.y-dy/len*36;let offset=e.kind==='pullback'?-48:e.kind==='norm'?48:0;let midx=(sx+tx)/2,midy=(sy+ty)/2+offset;path=`M${sx},${sy} Q${midx},${midy} ${tx},${ty}`;lx=midx;ly=(sy+ty)/2+offset/2-6}let label=e.kind==='isogeny'?'2-isog.':e.kind==='cover'?`π · ${e.degree}:1`:e.kind==='pullback'?'π*':'π_*';return `<g class="edge ${selected===e.id?'selected':''}" data-edge="${e.id}" tabindex="0" role="button" aria-label="${e.kind} from ${e.source} to ${e.target}"><title>${e.kind}: ${e.source} → ${e.target}</title><path class="edge-hit" d="${path}"/><path class="edge-line" d="${path}" stroke="${edgeColors[e.kind]}" ${['norm','pullback'].includes(e.kind)?'stroke-dasharray="4 5"':''} marker-end="url(#arrow-${e.kind})"/><text x="${lx}" y="${ly}" text-anchor="middle" fill="${edgeColors[e.kind]}">${label}</text></g>`}).join('');
let nodes=data.nodes.map(n=>{let p=pos.get(n.id),color=colors[n.kind],r=n.id==='E0'?37:28;return `<g class="node ${selected===n.id?'selected':''}" data-node="${n.id}" transform="translate(${p.x} ${p.y})" tabindex="0" role="button" aria-label="${n.label}, ${n.kind}, ${n.kind==='jacobian'?'dimension':'genus'} ${n.genus}"><title>${n.label} · ${n.kind} · ${n.genus}</title><circle class="halo" r="${r+12}" fill="${color}"/><circle r="${r}" fill="#141e2a" stroke="${color}" stroke-width="${n.id==='E0'?2:1.3}" ${n.kind==='jacobian'?'stroke-dasharray="3 3"':''}/><text text-anchor="middle" y="5" fill="${color}" style="font: ${n.kind==='jacobian'?14:19}px Georgia,serif">${n.label}</text><text text-anchor="middle" y="${r+20}" fill="#9eacbd" style="font:10px sans-serif">${n.kind==='jacobian'?'dim':'g'} = ${n.genus}${n.id==='E0'?' · base':''}</text></g>`}).join('');
$('#graph').setAttribute('viewBox',`0 0 1000 ${height}`);$('#graph').innerHTML=`<defs>${defs}</defs><g transform="translate(${500*(1-zoom)} ${height/2*(1-zoom)}) scale(${zoom})">${edges}${nodes}</g>`;$('#zoomLabel').textContent=Math.round(zoom*100)+'%';$('#empty').hidden=data.nodes.length!==1;$('#empty').textContent='No outgoing rational 2-isogenies found and no valid covers in this search. Try another curve or shift.';
 document.querySelectorAll('[data-node],[data-edge]').forEach(el=>{const select=()=>{selected=el.dataset.node||el.dataset.edge;inspect();draw()};el.onclick=select;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});}
function inspect(){const n=data.nodes.find(n=>n.id===selected),e=data.edges.find(e=>e.id===selected);if(n){let title=n.kind==='elliptic'?eq(n):n.kind==='jacobian'?`J(${data.nodes.find(c=>c.id===n.curve).label})`:n.equation.replace(/\^(\d+)/g,(_,a)=>sup(a));$('#details').innerHTML=`<span class="tag">${n.kind} · ${n.label}</span><div class="math">${title}</div><div class="detail-grid"><div><small>${n.kind==='jacobian'?'Dimension':'Genus'}</small><strong>${n.genus}</strong></div><div><small>Base field</small><strong>𝔽${data.parameters.p}</strong></div>${n.count?`<div><small>#E(𝔽ₚ)</small><strong>${n.count}</strong></div>`:''}${n.id==='E0'?`<div><small>j-invariant</small><strong>${data.j}</strong></div>`:''}</div><p>${n.kind==='elliptic'?'Select an edge to inspect its kernel, degree and map formula. Rational 2-torsion kernels generate the displayed isogenies.':n.kind==='jacobian'?'The degree-zero Picard variety of this cover. Dashed arrows are pullback and norm homomorphisms, whose coordinates are not explicitly computed.':`${n.classification}. Select its arrow to E₀ for the explicit covering map. Genus refers to the smooth projective model.`}</p>`}else if(e){$('#details').innerHTML=`<span class="tag">${e.kind} · ${e.source} → ${e.target}</span><div class="math">${e.formula}</div><div class="detail-grid"><div><small>Map type</small><strong>${e.kind}</strong></div>${e.degree?`<div><small>Degree</small><strong>${e.degree}</strong></div>`:''}${e.kernel!==undefined?`<div><small>Kernel point</small><strong>(${e.kernel}, 0)</strong></div>`:''}</div><p>${e.detail}</p>`}}
function generate(e){e?.preventDefault();try{const next=build({p:Number($('#p').value),a:Number($('#a').value),b:Number($('#b').value),c:Number($('#c').value),maxN:Number($('#n').value),depth:Number($('#depth').value),quartic:$('#quartic').checked,jacobians:$('#jacobians').checked});data=next;selected='E0';zoom=1;$('#error').textContent='';$('#heroEquation').textContent=eq(data.nodes[0]);$('#field').textContent=`Over 𝔽${data.parameters.p} · nonsingular`;$('#graphCount').textContent=`${data.nodes.length} objects / ${data.edges.length} maps`;$('#statE').textContent=data.nodes.filter(n=>n.kind==='elliptic').length;$('#statC').textContent=data.nodes.filter(n=>n.kind==='hyperelliptic'||n.kind==='superelliptic').length;$('#statG').textContent=Math.max(...data.nodes.map(n=>n.genus));$('#statM').textContent=data.edges.length;$('#scopeText').textContent=data.scope;$('#warnings').textContent=data.skipped.join(' ');inspect();draw()}catch(err){$('#error').textContent=err.message}}
function download(content,type,name){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('#form').onsubmit=generate;$('#n').oninput=()=>$('#nValue').textContent=`n ≤ ${$('#n').value}`;$('#reset').onclick=()=>{$('#form').reset();$('#nValue').textContent='n ≤ 3';generate()};$('#plus').onclick=()=>{zoom=Math.min(2,zoom+.15);draw()};$('#minus').onclick=()=>{zoom=Math.max(.5,zoom-.15);draw()};$('#fit').onclick=()=>{zoom=1;draw()};$('#export').onclick=()=>download(JSON.stringify(data,null,2),'application/json','curve-atlas.json');$('#svgExport').onclick=()=>{const svg=$('#graph').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.insertAdjacentHTML('afterbegin',`<style>.edge-line{fill:none;stroke-width:1.4}.edge-hit{fill:none;stroke:none}.halo{opacity:0}.edge text{font:10px sans-serif;paint-order:stroke;stroke:#101722;stroke-width:5px}</style><rect width="100%" height="100%" fill="#101722"/>`);download(new XMLSerializer().serializeToString(svg),'image/svg+xml','curve-atlas.svg')};$('#method').onclick=()=>$('#about').showModal();$('#closeAbout').onclick=()=>$('#about').close();generate();
